    "question": "float 型数据通常用 IEEE754 单精度浮点数格式表示。若编译器将 float 型变量 x 分配在一个 32 位浮点寄存器 FR1 中，且 x=-8.25，则 FR1 的内容是（ ）。 A. C1040000H B. C2420000H C. C1840000H D. C1C20000H",
