    "typeName": "选择题",
    "score": 2,
    "question": "下列命中组合情况中，一次访存过程中不可能发生的是（ ）。 A. TLB 未命中，Cache 未命中，Page 未命中 B. TLB 未命中，Cache 命中，Page 命中 C. TLB 命中，Cache 未命中，Page 命中 D. TLB 命中，Cache 命中，Page 未命中",
    "answer": "D",
    "analysis": "Cache 中存放的是主存的一部分副本，TLB（快表）中存放的是 Page（页表）的一部分副本。在同时具有虚拟页式存储器（有 TLB）和 Cache 的系统中，CPU 发出访存命令，先查找对应的 Cache 块。 若 Cache 命中，则说明所需内容在 Cache 内，其所在页面必然已调入主存，因此 Page 必然命中，但 TLB 不一定命中。 若 Cache 不命中，并不能说明所需内容未调入主存，和 TLB、Page 命中与否没有联系。但若 TLB 命中，Page 也必然命中；而当 Page 命中，TLB 则未必命中，故 D 不可能发生。 【提示】本题看似既涉及虚拟存储器又涉及 Cache，实际上这里并不需要考虑 Cache 命中与否。因为一旦缺页，说明信息不在主存，那么 TLB 中就一定没有该页表项，所以不存在 TLB 命中、Page 缺失的情况，也根本谈不上访问 Cache 是否命中。",
    "steps": [
      "Cache 中存放的是主存的一部分副本，TLB（快表）中存放的是 Page（页表）的一部分副本。",
      "在同时具有虚拟页式存储器（有 TLB）和 Cache 的系统中，CPU 发出访存命令，先查找对应的 Cache 块。",
      "若 Cache 命中，则说明所需内容在 Cache 内，其所在页面必然已调入主存，因此 Page 必然命中，但 TLB 不一定命中。",
      "若 Cache 不命中，并不能说明所需内容未调入主存，和 TLB、Page 命中与否没有联系。",
      "但若 TLB 命中，Page 也必然命中；",
      "而当 Page 命中，TLB 则未必命中，故 D 不可能发生。"
    ],
