    "typeName": "应用题",
    "score": 9,
    "question": "2025年408综合题47（9分）：工程部网络通过天通一号地球同步卫星链路连接总部。卫星轨道高度36000km，电磁波传播速度300000km/s；R1-R2链路对称全双工，每方向速率200kbps。求单向传播时延、最大吞吐量、4000B文件上传时间；基于GBN设计单向可靠链路层协议，帧长1500B、忽略ACK长度，利用率至少80%，求发送窗口和序号位数；对10.10.10.0/24划分管理、生活、作业子网，已知管理区主机10.10.10.33/26，生活区至少120主机，作业和管理区各至少60主机，求作业区和生活区网络地址。",
    "answer": "单向传播时延=(2×36000)/300000=0.24s=240ms；最大吞吐量200kbps；4000B发送时延160ms，单向上传至少400ms。帧发送时间60ms、RTT=480ms，GBN利用率≥80%要求W≥7.2，窗口最小8；GBN序号至少4位。管理区主机属于10.10.10.0/26；作业区为10.10.10.64/26；生活区为10.10.10.128/25。",
    "analysis": "卫星单向链路包括地面上行和卫星下行两段传播距离，不能只按36000km计算。GBN的发送窗口通过带宽时延积决定；利用率公式分母为一个数据帧发送时间加往返传播时间。序号空间必须满足GBN发送窗口上限2^k−1。子网划分先确定已给管理区地址所在的/26网络，再从剩余地址中给60主机分配/26、给120主机分配/25，必须满足CIDR边界且不重叠。",
    "steps": [
      "地面到卫星再返回地面传播距离为2×36000=72000km，单向传播时延=72000/300000=0.24s=240ms。",
      "卫星链路每方向速率200kbps，是瓶颈，最大吞吐量为200kbps。",
      "4000B文件共32000bit，发送时延=32000/200000=0.16s=160ms；单向上传总时间=240+160=400ms。",
      "1500B数据帧发送时间Tf=1500×8/200000=0.06s=60ms；RTT=2×240=480ms。",
      "忽略ACK帧发送时间，GBN利用率U=W×Tf/(Tf+RTT)。令U≥0.8，W≥0.8×(60+480)/60=7.2，故最小整数W=8。",
      "GBN发送窗口满足W≤2^k−1，W=8时2^k≥9，故k最小为4位。",
      "10.10.10.33/26的网络地址为10.10.10.0/26，管理区占用.0～.63。",
      "作业区至少60台主机，/26有62个可用地址，分配10.10.10.64/26（主机.65～.126）。",
      "生活区至少120台主机，/25有126个可用地址，分配10.10.10.128/25（主机.129～.254）。"
    ],
