    "question": "内部异常（内中断）可分为故障（fault）、陷阱（trap）和终止（abort）三类。下列有关内部异常的叙述中，错误的是（ ）。 A. 内部异常的产生与当前执行指令相关 B. 内部异常的检测由 CPU 内部逻辑实现 C. 内部异常的响应发生在指令执行过程中 D. 内部异常处理后返回到发生异常的指令继续执行",
    "answer": "D",
    "analysis": "内部异常由当前指令执行引起，通常由 CPU 检测；故障处理后可能重新执行引发故障的指令，陷阱通常返回到下一条指令，终止则不保证能够继续执行。因此“所有内部异常处理后都返回到发生异常的指令继续执行”错误，选 D。",
    "steps": [
      "故障、陷阱和终止均与当前指令执行相关。",
      "异常由 CPU 执行逻辑检测并触发处理。",
      "fault 通常可在处理后重新执行当前指令；trap 通常返回下一条指令；abort 不保证恢复。",
      "D 将故障的返回语义错误推广到全部异常类型，选 D。"
    ],
