    "id": 465,
    "subject": "数据结构",
    "subjectCode": "data-structure",
    "typeName": "应用题",
    "score": 12,
    "question": "拟建设连通BJ、CS、XA、QD、JN、NJ、TL、WH八个城市的最经济光缆网络，求所有最小生成树、图存储结构、算法及TTL=5时的可达性。",
    "answer": "共有两棵最小生成树，总费用均为16。两方案共同边：XA—BJ(2)、XA—WH(2)、TL—JN(2)、QD—JN(2)、QD—NJ(2)、CS—QD(3)；第7条边分别选BJ—TL(3)或WH—QD(3)。图可用邻接矩阵或邻接表存储，算法可用Prim或Kruskal。TTL=5时，含BJ—TL边的方案可到达H2；另一方案在BJ路由器继续转发时TTL耗尽，H2收不到。",
    "analysis": "题目要求给出所有最经济方案，不能只写总费用。相同权值边导致多棵最小生成树；TTL判断必须沿实际生成树路径逐台路由器递减。",
    "steps": [
      "将城市和光缆费用抽象为无向带权图，经济铺设方案就是最小生成树。",
      "先选取权值为2且不构成回路的五条边：XA—BJ、XA—WH、TL—JN、QD—JN、QD—NJ，总费用10。",
      "为接入CS必须选择CS—QD(3)；连接左右分量可选择BJ—TL(3)或WH—QD(3)，因此有两棵MST。",
      "每棵树共7条边，总费用10+3+3=16。",
      "邻接矩阵适合稠密图，邻接表适合稀疏图；Prim逐步扩展生成树，Kruskal按边权排序并用并查集避免成环。",
      "TTL逐路由器转发递减：直连TL—BJ的方案可到达；另一方案需TL→JN→QD→WH→BJ，TTL在BJ路由器转发到H2前耗尽。"
    ],
