    "id": 467,
    "subject": "计算机组成原理",
    "subjectCode": "computer-organization",
    "typeName": "应用题",
    "score": 15,
    "question": "根据题44图分析页式虚拟存储、TLB映射、Cache映射/容量及两个虚拟地址的物理地址和Cache命中。",
    "answer": "物理地址28位；TLB全相联映射、用SRAM；Cache为2路组相联，8组、每块32B，Tag20位/组索引3位/块内偏移5位；参考答案容量4464bit=558B。0008C040H→0040040H且Cache不命中；0007C260H映射第3组。",
    "analysis": "先由TLB完成虚页号到实页号映射，再由物理地址访问Cache。命中必须同时满足有效位和Tag比较。",
    "steps": [
      "页内偏移12位、实页号16位，物理地址长度28位。",
      "TLB每项可放入任意空项，为全相联映射；TLB采用SRAM。",
      "每组两行，Cache为2路组相联；8组、每块32B，物理地址字段Tag20位、组号3位、块内偏移5位。",
      "LRU用于两路间替换，回写策略增加脏位；有效位为0表示该行无有效数据。参考答案计入每行1位LRU、1位脏位，容量4464bit=558B。",
      "0008C040H的虚页号008CH映射到实页号0040H，偏移040H，物理地址0040040H。组号2；Tag相等的行有效位为0，另一有效行Tag不匹配，故不命中。",
      "0007C260H页内偏移260H，其低8位01100000B中的组索引011B=3，映射第3组。"
    ],
    "code": "",
