    "question": "根据题44图，计算页目录号6、页号6、偏移8组成的虚拟地址，分析PDBR切换及改进型CLOCK字段。",
    "answer": "虚拟地址01806008H；PDBR保存页目录起始物理地址，进程切换时变化，同一进程线程切换时不变；改进型CLOCK需要访问位和修改位。",
