    "steps": [
      "32位虚拟地址中页内偏移12位，虚页号20位；二级页表将虚页号分为10位页目录号和10位页号。",
      "页目录号6、页号6分别写成10位二进制0000000110，偏移8写成12位000000001000。",
      "拼接字段得到0000000110 0000000110 000000001000，十六进制为01806008H。",
      "PDBR保存当前进程页目录的物理基地址。进程切换时地址空间和页目录变化，需更新PDBR；同一进程线程共享地址空间，PDBR不变。",
      "改进型CLOCK需访问位R和修改位M。"
    ],
