    "question": "索引节点含8个直接地址项及一级、二级、三级间接地址项，簇4KB、地址项4B，计算最大文件长度、文件数量和末簇寻址时间。",
    "answer": "最大文件长度=(8+1024+1024²+1024³)×4KB；inode最多64M个，5600B文件占2簇，最多存64M个；F1=6KB只需直接地址，F2=40KB需一级间接索引，访问时间不同。",
