    "score": 9,
    "question": "本题串联冲突域/广播域、CSMA/CD碰撞检测时延约束、DHCP初始发现报文广播及基础设施型WLAN三地址帧。交换机隔离冲突域但默认不隔离同VLAN广播域；Hub扩展同一冲突域。AP向无线站点转发帧时，地址1为接收站、地址2为AP、地址3保留原始以太网源地址。",
    "answer": "（1）设备1选100BaseT交换机，设备2选100BaseT集线器。（2）H2与H3最远距离210m。（3）M为DHCP Discover；路由器E0能收到该广播帧；S转发帧的目的MAC为FF-FF-FF-FF-FF-FF。（4）H5收到的802.11帧：地址1=H5 00-11-11-11-11-E1，地址2=AP 00-11-11-11-11-C1，地址3=H4 00-11-11-11-11-D1。",
    "analysis": "本题串联冲突域/广播域、CSMA/CD碰撞检测时延约束、DHCP初始发现报文广播及基础设施型WLAN三地址帧。交换机隔离冲突域但默认不隔离同VLAN广播域；Hub扩展同一冲突域。AP向无线站点转发帧时，地址1为接收站、地址2为AP、地址3保留原始以太网源地址。",
    "steps": [
      "H1与H2同广播域但不同冲突域，设备1需隔离冲突域且不切分广播域，因此选交换机。H2与H3同一冲突域，设备2必须共享冲突域，因此选Hub。",
      "100BaseT速率100Mb/s，64B最小帧发送时间=64×8/100Mb/s=5.12μs。往返传播与Hub转发延迟满足5.12=2×(1.51+D/(2×10^8)) μs。",
      "解得单程线路传播时间=1.05μs，D=1.05×10^-6×2×10^8=210m。",
      "H4首次获取地址发送DHCP Discover，客户端尚无IP地址，采用广播；同一广播域内路由器E0接口可以收到该以太网广播帧。",
      "交换机向DHCP服务器转发封装Discover的广播帧时，目的MAC地址仍为FF-FF-FF-FF-FF-FF。",
      "H4经AP向H5发送数据，AP转发给无线终端H5时，To DS=0、From DS=1：地址1为最终接收站H5，地址2为发送该无线帧的AP，地址3为原始源H4。"
    ],
