    "question": "时间局部性要求重复访问同一数据，本题每元素只访问一次；空间局部性来自一个32B块含8个连续int。列优先虽然跨行访问，但每组只占3路，4路Cache能容纳，因此两种顺序命中率相同。数组长度0x1800跨两个4KB页面。",
    "answer": "（1）数组占2页，缺页2次，故障地址00422000H、00423000H。（2）每个元素仅访问一次，无时间局部性。（3）块内地址A4~A0，组号A10~A5；a[1][0]=00422100H，组号8。（4）占192块，两种循环顺序Cache命中率均87.5%。",
    "analysis": "时间局部性要求重复访问同一数据，本题每元素只访问一次；空间局部性来自一个32B块含8个连续int。列优先虽然跨行访问，但每组只占3路，4路Cache能容纳，因此两种顺序命中率相同。数组长度0x1800跨两个4KB页面。",
    "steps": [
      "数组字节数=24×64×4=6144B=0x1800B；从00422000H开始，覆盖00422H和00423H两页，首次访问各缺页一次。",
      "每个元素只写一次，因此不具有时间局部性；但相邻元素仍有空间局部性。",
      "块大小32B=2^5，块内偏移为A4~A0。Cache共8KB/32B=256块，4路得到64组，组号占A10~A5。",
      "a[1][0]地址=00422000H+1×64×4=00422100H；(地址>>5)&63=8。",
      "数组共6144/32=192块，每块容纳8个int。按行访问每块1次缺失、7次命中，命中率7/8。",
      "按列访问时行跨度256B；24行映射到64组，每组对应3个数组块，不超过4路，不发生数组内部替换；每块8个元素仍为7/8命中率。"
    ],
