      "立即数字节0A 00 00 00表示0x0000000A，低有效字节在低地址，故为小端。",
      "第19条指令位于004010AEH所属代码页00401H；程序执行到此处说明代码页已在主存，取指不再缺页。数组数据页缺页与代码页取指缺页是两回事。"
