    "id": 585,
    "subject": "计算机网络",
    "subjectCode": "computer-network",
    "typeName": "应用题",
    "score": 9,
    "question": "SYN和FIN各消耗一个TCP序号。数据从初始序号+1开始；FIN在全部文件字节后发送，服务器确认号再加1。拥塞窗口按题设初始阈值4MSS及无丢包过程演进。应用层吞吐率只用文件净数据量除以总时间。",
    "answer": "（1）FTP控制连接持久、数据连接非持久；登录建立控制连接。（2）文件首字节序号101；服务器第二次挥手ACK=18102。（3）ACK=2101时cwnd=3MSS；ACK=7101时cwnd=5MSS。（4）6RTT=60ms；平均速率0.3MB/s=2.4Mb/s。",
    "analysis": "SYN和FIN各消耗一个TCP序号。数据从初始序号+1开始；FIN在全部文件字节后发送，服务器确认号再加1。拥塞窗口按题设初始阈值4MSS及无丢包过程演进。应用层吞吐率只用文件净数据量除以总时间。",
    "steps": [
      "FTP控制连接用于命令与响应，贯穿会话；数据连接用于文件传输，传输后释放。登录时建立的是控制连接。",
      "TCP SYN消耗一个序号，初始序号100后，文件首字节序号为101。",
      "18000B/MSS1000B=18段。末字节序号=101+18000−1=18100；主机FIN序号18101，FIN再消耗一个序号，服务器ACK=18102。",
      "按题设慢开始和拥塞避免过程，累计确认号2101时窗口为3MSS；确认号7101时窗口为5MSS。",
      "请求建立数据连接至服务器确认文件接收共至少6RTT；6×10ms=60ms。",
      "平均应用层速率=18000B/0.06s=300000B/s=0.3MB/s=2.4Mb/s。"
    ],
