    "typeName": "应用题",
    "score": 10,
    "question": "2025年408综合题42（10分）：给定含7个事件顶点、12个活动的AOE网。边及持续时间为：a:1→3(2)，b:1→2(5)，d:1→4(3)，e:3→4(3)，c:3→6(1)，f:4→2(4)，g:4→6(1)，j:4→5(1)，m:4→7(4)，h:6→7(1)，k:2→5(2)，n:7→5(3)。求工程最短完成时间和关键活动；与e同时进行的活动；时间余量最大的活动及余量；若b在时刻6开始，b持续时间最多多少，若b保持原持续时间则压缩哪个活动。",
    "answer": "工程最短完成时间为12；关键活动为a、e、m、n（关键路径1→3→4→7→5）。活动e执行区间为[2,5]，可与b、d、c同时进行。总时差最大的活动为j，余量6。b在时刻6开始时，持续时间最多4；若b仍为5，则将k从2压缩到1即可保证工期不延期。",
    "analysis": "AOE网工程最短完成时间等于关键路径长度。活动总时差用最迟开始减最早开始计算；本题j活动的总时差为6。并行活动看其最早执行区间是否与e的[2,5]重叠。最后一问是对路径1→2→5做工期约束：b被推迟到6后，b+k最多只能占用剩余6个时间单位。",
    "steps": [
      "正向求事件最早时间ve：节点1～7分别为0、9、2、5、12、6、9。",
      "反向求事件最迟时间vl：节点1～7分别为0、10、2、5、12、8、9。",
      "由1→3→4→7→5得到路径长度2+3+4+3=12，为关键路径；关键活动a、e、m、n。",
      "活动e最早在ve(3)=2开始，持续3，到时刻5结束；b区间[0,5]、d区间[2,5]、c区间[2,3]，均与e重叠。",
      "活动i→j持续w的总时差为TF=vl(j)-ve(i)-w。活动j(4→5)的TF=12-5-1=6，为最大。",
      "b在时刻6开始，路径1→2→5剩余路径时长为6+b+2，必须不超过12，故b≤4。",
      "若b仍为5，则6+5+k≤12，k≤1；将k由2缩短至1即可。"
    ],
