    "index": 45,
    "id": 597,
    "subject": "操作系统",
    "subjectCode": "operating-system",
    "typeName": "应用题",
    "score": 7,
    "question": "2025年408综合题45（7分）：甲挖树坑，乙将树苗放入树坑并填土，丙为新种树苗浇水。顺序为挖坑、放树苗、填土、浇水。铁锹1把，用于挖坑和填土；水桶1个，用于浇水。当未被乙使用的树坑数量小于3时甲才可继续挖坑。初始树坑数量0，铁锹和水桶均可用。用尽可能少的信号量和wait/signal描述三人同步互斥。",
    "answer": "设置4个信号量：mutex=1（铁锹互斥）、pits=3（最多允许3个未被乙使用的树坑）、empty=0（已挖好、待乙使用的树坑数）、water=0（待丙浇水的树苗数）。甲wait(pits)、wait(mutex)、挖坑、signal(mutex)、signal(empty)；乙wait(empty)、wait(mutex)、放苗并填土、signal(mutex)、signal(pits)、signal(water)；丙wait(water)、浇水。水桶仅由丙使用，不需额外互斥信号量。",
    "analysis": "这是三阶段生产流水线加容量为3的有界中间缓冲区。甲生产“已挖树坑”，乙消费树坑并生产“待浇水树苗”，丙消费待浇水树苗。pits控制未被乙处理的坑数量上限，empty和water建立相邻阶段先后关系，mutex保护甲乙共享的铁锹。题目要求信号量尽可能少，因此不为单一执行者丙使用的水桶另设互斥锁。",
    "steps": [
      "pits初值3表示甲最多可先挖3个未被乙处理的坑；每挖一个wait(pits)，乙处理完一个坑后signal(pits)。",
      "empty初值0表示开始没有已挖好的坑；甲挖好后signal(empty)，乙先wait(empty)才能放苗填土。",
      "mutex初值1保护铁锹，因为甲和乙会竞争同一把铁锹；使用前wait，使用后signal。",
      "water初值0表示开始没有待浇水的树苗；乙完成放苗填土后signal(water)，丙wait(water)后浇水。",
      "丙是唯一使用水桶的执行者，因此不需要额外水桶互斥量。"
    ],
