    "question": "2025年408综合题46（8分）：给定进程虚拟地址空间图及C程序：全局变量char *ptr; main中定义int length；ptr=(char*)malloc(100); scanf(\"%s\",ptr); length=strlen(ptr); printf(\"length=%d\\n\",length); free(ptr)。问PCB所在区域及scanf等待键盘时进程状态；main代码段及需要驱动程序实现的直接调用函数；ptr、length及ptr指向字符串分别位于哪个区域。",
    "answer": "PCB位于操作系统内核区；scanf等待键盘输入时进程处于阻塞态。main代码位于只读代码段；scanf和printf的终端I/O功能需要设备驱动程序支持。ptr是全局指针变量，位于读写数据段；length是局部自动变量，未分配寄存器时位于用户栈；ptr指向的malloc动态分配字符串位于堆区。",
    "analysis": "本题区分变量本身与指针指向对象的存储位置。全局指针ptr本身放在读写数据段，但malloc创建的目标缓冲区放在堆。局部变量length通常在栈。I/O库函数scanf和printf经由系统调用/内核I/O层使用设备驱动，等待键盘输入时进程阻塞。",
    "steps": [
      "PCB由操作系统内核管理，放在内核区。",
      "scanf等待键盘输入属于阻塞式I/O，进程等待输入事件时进入阻塞态。",
      "main函数机器指令属于只读代码段（.text）。",
      "scanf从键盘读取、printf向终端输出，最终需要相应设备驱动支持；strlen、malloc和free本身不是设备驱动操作。",
      "ptr声明在main外，是全局变量，指针变量本身位于读写数据段。",
      "length声明在main内部，是局部自动变量；若未分配寄存器，通常位于用户栈。",
      "malloc(100)分配的100字节对象位于动态堆；ptr保存该对象的地址。"
    ],
